#' Tumor Budding (ITBCC)
#'
#' Quantifies tumor budding and assigns an ITBCC (2016) grade from the number 
#' of buds counted in a hotspot. Supports a single hotspot count, multiple 
#' candidate fields (hotspot = the densest field), and area normalization to 
#' the standard 0.785 mm2 field.
#' 
#' @param data .
#' @param budCount Number of tumor buds counted. With multiple fields per case
#'   (see Case ID), the densest field is taken as the hotspot.
#' @param caseId Optional case identifier. When several rows share a case ID
#'   (multiple fields), the maximum bud count is used as the hotspot for that
#'   case.
#' @param fieldArea Area of the counted field in mm2. Counts are normalized to
#'   the ITBCC standard 0.785 mm2 field (20x objective, 0.55 mm field diameter)
#'   before grading.
#' @param group .
#' @param survivalTime .
#' @param survivalStatus .
#' @param eventLevel .
#' @param showGrading .
#' @param showPerCase .
#' @param showSurvival .
#' @param showPlot .
#' @param showSummary .
#' @param showExplanation .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$gradingTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$perCaseTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$survivalTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$addGradeToData} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$gradingTable$asDF}
#'
#' \code{as.data.frame(results$gradingTable)}
#'
#' @export
tumorbudding <- function(
    data,
    budCount,
    caseId,
    fieldArea = 0.785,
    group,
    survivalTime,
    survivalStatus,
    eventLevel,
    showGrading = TRUE,
    showPerCase = FALSE,
    showSurvival = TRUE,
    showPlot = TRUE,
    showSummary = TRUE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("tumorbudding requires jmvcore to be installed (restart may be required)")

    if ( ! missing(budCount)) budCount <- jmvcore::resolveQuo(jmvcore::enquo(budCount))
    if ( ! missing(caseId)) caseId <- jmvcore::resolveQuo(jmvcore::enquo(caseId))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(survivalTime)) survivalTime <- jmvcore::resolveQuo(jmvcore::enquo(survivalTime))
    if ( ! missing(survivalStatus)) survivalStatus <- jmvcore::resolveQuo(jmvcore::enquo(survivalStatus))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(budCount), budCount, NULL),
            `if`( ! missing(caseId), caseId, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(survivalTime), survivalTime, NULL),
            `if`( ! missing(survivalStatus), survivalStatus, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- tumorbuddingOptions$new(
        budCount = budCount,
        caseId = caseId,
        fieldArea = fieldArea,
        group = group,
        survivalTime = survivalTime,
        survivalStatus = survivalStatus,
        eventLevel = eventLevel,
        showGrading = showGrading,
        showPerCase = showPerCase,
        showSurvival = showSurvival,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- tumorbuddingClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

